            $this->name,
            $this->status,
            $this->created,
            $this->publicNet,
            $this->privateNet,
            $this->serverType,
            $this->location,
            $this->image,
            $this->iso,
            $this->rescueEnabled,
            $this->locked,
            $this->backupWindow,
            $this->outgoingTraffic,
            $this->ingoingTraffic,
            $this->includedTraffic,
            $this->protection,
            $this->labels,
            $this->primaryDiskSize,
            $this->volumes,
            $this->loadBalancers,
            $this->placementGroup,
            $this->additionalProperties,
        );
    }
}
